## 3. Componente Blazor Principal (`DownloadProgress.razor`)

```razor
@page "/download"
<script type="module">
  import { inject } from 'blazor.webassembly.js';
  const http = inject(httpClient);

  let items = @([] as DownloadItem[]);
  let serverStatus = ServerStatus.Connecting;
  let currentIdx = -1;
  let retrying = false;
  let totalFiles = 0;
  let totalBytes = 0;
  let downloadedBytes = 0;
  let fileName = '';
  let progressPercent = 0;
  let msg = '';
  let countdownTimer: number | null = null;

  function init() {
    loadItems();
  }

  async function loadItems() {
    // Busca os itens configurados (via JS ou config estática)
    const config = await fetch('/api/download/config').then(r => r.json());
    items = config.items;
    totalFiles = config.items.length;
    totalBytes = config.items.reduce((s, i) => s + i.expectedSizeBytes || 0, 0);
  }

  async function connect() {
    msg = 'Conectando ao servidor...';
    serverStatus = ServerStatus.Connecting;
    try {
      const res = await http.post('/api/download/status', {}, 'text');
      if (res.status === 404) {
        msg = 'Erro: Arquivo/servidor não encontrado (404)';
        startCountdown();
        serverStatus = ServerStatus.Error404;
        return;
      }
      if (res.status === 503) {
        msg = 'Servidor indisponível';
        serverStatus = ServerStatus.ErrorUnavailable;
        return;
      }
      if (res.status === 403) {
        msg = 'Acesso negado';
        serverStatus = ServerStatus.AccessDenied;
        return;
      }
      msg = 'Conectado!';
      serverStatus = ServerStatus.Authenticating;
    } catch (e) {
      msg = 'Não foi possível conectar ao servidor';
      serverStatus = ServerStatus.ErrorUnavailable;
    }
    updateUI();
  }

  async function authenticate() {
    msg = 'Autenticando no servidor...';
    serverStatus = ServerStatus.Authenticating;
    try {
      const res = await http.post('/api/download/auth', { user: 'system' }, 'text');
      if (!res.ok) {
        msg = `Autenticação falhou: ${res.statusText}`;
        serverStatus = ServerStatus.ErrorUnavailable;
        return;
      }
      msg = 'Autenticação do servidor concluída ✓';
      serverStatus = ServerStatus.Ready;
    } catch (e) {
      msg = `Erro na autenticação: ${e.message}`;
      serverStatus = ServerStatus.ErrorUnavailable;
    }
    updateUI();
  }

  async function startAll() {
    msg = 'Preparando para iniciar o download...';
    serverStatus = ServerStatus.Ready;
    await new Promise(r => setTimeout(r, 800));
    msg = 'Iniciando downloads...';
    serverStatus = ServerStatus.Downloading;
    currentIdx = -1;
    processNext();
  }

  async function processNext() {
    if (currentIdx >= items.length) {
      msg = 'Todos os arquivos foram processados!';
      serverStatus = ServerStatus.Completed;
      stopCountdown();
      return;
    }
    const item = items[currentIdx];
    currentIdx++;
    fileName = item.fileName;
    msg = `Baixando arquivo (${formattedCurrentFile} / ${totalFiles}): ${item.fileName}`;

    // Conta regressiva de timeout por arquivo (começa em 30s até 0)
    stopCountdown();
    countdownTimer = window.setTimeout(() => {
      onTimeout(item);
    }, 30000);

    try {
      serverStatus = ServerStatus.Downloading;
      const result = await callDownloadApi(item);
      clearTimeout(countdownTimer);
      handleResult(result, item);
    } catch (e) {
      clearTimeout(countdownTimer);
      onNetworkError(item);
    }
  }

  async function callDownloadApi(item: DownloadItem): Promise<boolean> {
    // Chamada ao backend Blazor que faz o download resumível
    const res = await http.post('/api/download/file', { version: item.version, filename: item.fileName });
    // O backend retorna sucesso/falha + updates de progresso via WebSocket ou polling
    return res.success;
  }

  function handleResult(success: boolean, item: DownloadItem) {
    if (success) {
      msg = `OK — ${item.fileName} (${formatBytes(downloadedBytes)})`;
      if (item.integrityHash) verifyHash(item);
      else markDone(item);
    } else {
      msg = `Falha em ${item.fileName} — reiniciando...`;
      retryItem(item);
    }
  }

  function verifyHash(item: DownloadItem) {
    // Backend verifica hash e responde ok/não-ok
    fetch(`/api/download/verify?v=${item.version}&f=${item.fileName}`).then(r => {
      if (r.ok) {
        msg = `${item.fileName} validado ✓`;
      } else {
        msg = `${item.fileName} hash inválido — será rebaixado`;
        retryItem(item);
      }
      updateUI();
    });
  }

  function markDone(item: DownloadItem) {
    // Marca como feito e avança pro próximo
    // Atualiza estado via SignalHub ou callback JS→CS
    emitProgress({ index: currentIdx, done: true, file: item.fileName });
    if (currentIdx < items.length - 1) processNext();
    else finish();
  }

  function retryItem(item: DownloadItem) {
    msg = `Reiniciando o download de ${item.fileName}...`;
    retrying = true;
    setTimeout(() => processNext(), 3000); // pausa curta entre retries
  }

  function onNetworkError(item: DownloadItem) {
    msg = `Reiniciando o download de ${item.fileName}...`;
    retrying = true;
    setTimeout(() => processNext(), 5000);
  }

  function onTimeout(item: DownloadItem) {
    msg = `Tempo esgotado em ${item.fileName} — tentando novamente...`;
    retryItem(item);
  }

  function finish() {
    msg = 'Download concluído com sucesso! 🎉';
    serverStatus = ServerStatus.Completed;
  }

  function formatBytes(b: number): string {
    if (b < 1024) return b + ' B';
    if (b < 1024 * 1024) return (b / 1024).toFixed(1) + ' KB';
    return (b / (1024 * 1024)).toFixed(1) + ' MB';
  }

  function formattedCurrentFile(): string {
    const done = items.filter(i => i.done).length;
    return `${done} / ${totalFiles}`;
  }

  function updateUI() {
    // Atualiza propriedades do componente
    this.fileName = fileName;
    this.progressPercent = progressPercent;
    this.downloadedBytes = downloadedBytes;
    this.msg = msg;
    this.serverStatus = serverStatus;
    this.currentIdx = currentIdx;
  }

  // Sinalização para Razor (via SignalHub ou evento custom)
  emitProgress = (data: any) => {
    // Em Blazor WebAssembly usa-se SignalHub ou comunica via postback
    // Alternativa: usar @onparamChange com param="progress"
  };

  onParamChange = (e: CustomEvent) => {
    const data = e.detail;
    if (data.index !== undefined) {
      currentIdx = data.index;
    }
    if ('percent' in data) progressPercent = data.percent;
    if ('bytes' in data) downloadedBytes = data.bytes;
    if ('msg' in data) msg = data.msg;
    if ('status' in data) serverStatus = data.status as any;
    updateUI();
  };
</script>

<div className="absolute bottom-3 rounded-lg w-[71%] h-[8%] flex flex-col justify-between items-center bg-[#0E1622]/[0.95] text-white">
