    {{ formattedCurrentFile() }}
    <span className="text-[#d16b2b] px-2 py-1 rounded ml-2">{{ fileName }}</span>
    ({{ msg }})
    <div className="text-[#38D12B] text-opacity-[0.95] mt-1">
      {{ formatBytes(downloadedBytes) }} / {{ formatBytes(totalBytes) }}
