## 4. API Blazor Backend (`Program.cs` + Controller)

```csharp
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using MyApp.Services;

var builder = WebApplication.CreateBuilder(args);

// Registra o serviço de download
builder.Services.AddSingleton<IDownloadService>(sp =>
{
    var env = sp.GetService<IWebHostEnvironment>();
    var exePath = env.ApplicationPath + "/" + Environment.GetExecutablePath();
    return new DownloadService(sp.GetRequiredService<HttpClient>(), builder.Configuration["BaseUrl"], exePath);
});

var app = builder.Build();

app.MapPost("/api/download/status", async (IDownloadService svc, HttpResponse resp) =>
{
    var s = await svc.ConnectAsync();
    resp.StatusCode = (int)s switch
    {
        ServerStatus.Ready       => 200,
        ServerStatus.Error404    => 404,
        ServerStatus.ErrorUnavailable => 503,
        ServerStatus.AccessDenied => 403,
        _                        => 200 // coloca status em JSON
    };
    // Retorna JSON com detalhes se quiser mais info
    return Results.Ok(s.ToString());
});

app.MapPost("/api/download/auth", async (string json, IDownloadService svc, HttpResponse resp) =>
{
    var body = JsonSerializer.Deserialize(json, new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
    var token = await svc.AuthenticateAsync(body?.AuthToken ?? "");
    resp.ContentType = "application/json";
    await resp.WriteAsJsonAsync(new { success = token.Success, message = token.Message, token = token.AuthToken });
});

app.MapPost("/api/download/file", async (DownloadRequest req, IDownloadService svc, HttpResponse resp) =>
{
    var item = new DownloadItem
    {
        Version = req.Version,
        FileName = req.FileName,
        IntegrityHash = "", // preencher a partir da lista de updates
        ExpectedSizeBytes = 0
    };
    // Aqui você carrega a lista de updates e resolve qual item corresponde
    var status = await svc.DownloadAsync(item);
    resp.StatusCode = (int)(status == ServerStatus.Completed ? 200 : 502);
    await resp.WriteAsJsonAsync(status);
});

app.MapPost("/api/download/verify", async (VerifyReq req, IDownloadService svc, HttpResponse resp) =>
{
    // Verifica hash local do arquivo já baixado
    var ok = await svc.VerifyIntegrityAsync(/* resolver item */, /* caminho */);
    resp.ContentType = "application/json";
    await resp.WriteAsJsonAsync(new { valid = ok });
});

app.UseStaticFiles();
app.Run();

record DownloadRequest(int Version, string FileName);
record VerifyReq(string Version, string FileName, string FilePath);
