```csharp
using System.IO;
using System.Net.Http;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc.WebAssembly.Friendly;

namespace MyApp.Services;

public interface IDownloadService
{
    Task<ServerStatus> ConnectAsync();
    Task<ServerResponse> AuthenticateAsync(string authToken);
    Task<ServerStatus> PrepareAsync();
    Task<ServerStatus> DownloadAsync(DownloadItem item, CancellationToken ct = default);
    Task<ServerStatus> RetryAsync(DownloadItem item, CancellationToken ct = default);
    Task<bool> VerifyIntegrityAsync(DownloadItem item, string filePath);
    Task StartAsync(CancellationToken ct = default);
    EventWaitHandle StopRequested { get; }
}

public class DownloadService : IDownloadService
{
    private readonly HttpClient _http;
    private readonly string _baseUrl;
    private readonly string _patchDir;           // pasta patch junto ao exe
    private readonly string _lockFile;           // lock .lock para thread safety
    private readonly ManualResetEvent _stop = new();
    private HashSet<string> _inFlight = new();   // chaves por FileName+Version
    private Dictionary<string, DownloadState> _states = new();

    public EventWaitHandle StopRequested => new ManualResetEvent(false);

    public DownloadService(HttpClient http, string baseUrl, string executablePath)
    {
        _http = http;
        _baseUrl = baseUrl;
        var appDir = Path.GetDirectoryName(executablePath)!;
        _patchDir = Path.Combine(appDir, "patch");
        _lockFile = Path.Combine(_patchDir, "download.lock");
        Directory.CreateDirectory(_patchDir);
    }

    // ---------- Helpers ----------

    private static string EnsurePatchDir()
    {
        var d = Path.Combine(Path.GetDirectoryName(Environment.ExecutablePath)!, "patch");
        Directory.CreateDirectory(d);
        return d;
    }

    private async Task<string> GetAuthTokenAsync()
    {
        // Ajuste conforme seu servidor: pode ser POST /auth com JSON ou header
        using var request = new HttpRequestMessage(Method.Post, $"{_baseUrl}/auth");
        request.Content.ContentType = "application/json";
        request.Content.ReadAsStringAsync().Wait(); // placeholder - substitua pela real implementation
        // Exemplo simples: se o servidor só exige aceitar um cookie/session fixo
        // você pode pular isso e usar o token que já existe no servidor.
        return "";
    }

    // ---------- Público ----------

    public async Task<ServerStatus> ConnectAsync()
    {
        try
        {
            using var req = new HttpRequestMessage(Method.Get, $"{_baseUrl}/status");
            var resp = await _http.SendAsync(req, CancellationToken.None);
            if (resp.StatusCode == System.Net.HttpStatusCode.NotFound)
                return ServerStatus.Error404;
            if (resp.StatusCode == System.Net.HttpStatusCode.ServiceUnavailable)
                return ServerStatus.ErrorUnavailable;
            if (resp.StatusCode == System.Net.StatusCodes.Status403Forbidden)
                return ServerStatus.AccessDenied;

            // Lê JSON de status do servidor
            var body = await resp.Content.ReadAsStringAsync();
            // Pode vir como texto puro também — adapte conforme necessário
            Console.WriteLine($"[Connect] HTTP {resp.StatusCode} - {body.Substring(0, Math.Min(200, body.Length))}");
            return ServerStatus.Ready;
        }
        catch (HttpRequestException ex) when (ex.StatusCode == System.Net.HttpStatusCode.Unauthorized)
        {
            return ServerStatus.AccessDenied;
        }
        catch
        {
            return ServerStatus.ErrorUnavailable;
        }
    }

    public async Task<ServerResponse> AuthenticateAsync(string token)
    {
        try
        {
            using var req = new HttpRequestMessage(Method.Post, $"{_baseUrl}/auth");
            req.Headers.Add("Authorization", $"Bearer {token}");
            req.Content.ContentType = "application/json";
            var body = Encoding.UTF8.GetBytes("{\"user\":\"system\"}");
            req.Content = NewStringContent(body);

            var resp = await _http.SendAsync(req, CancellationToken.None);
            if (!resp.IsSuccessStatusCode)
                return new ServerResponse { Success = false, Message = $"Autenticação falhou: HTTP {resp.StatusCode}" };

            var json = await resp.Content.ReadAsStringAsync();
            // Descompacta JSON se vier compactado
            var decoded = JsonUtility.Decode(json);
            return new ServerResponse { Success = true, Message = "Autenticação OK", AuthToken = decoded?.Get("token", "") ?? "" };
        }
        catch (HttpRequestException ex)
        {
            return new ServerResponse { Success = false, Message = $"Erro rede: {ex.Message}" };
        }
    }

    public async Task<ServerStatus> PrepareAsync()
    {
        Console.WriteLine("[Prepare] Preparando para iniciar o download...");
        await Task.Delay(500); // simula preparação
        return ServerStatus.Ready;
    }

    /// <summary>
    /// Baixa o arquivo de forma RESUMÍVEL: grava em chunk de 1MB e verifica
    /// o último bloco gravado antes de continuar após interrupção.
    /// </summary>
    public async Task<ServerStatus> DownloadAsync(DownloadItem item, CancellationToken ct = default)
    {
        if (_inFlight.Contains($"{item.Version}:{item.FileName}") || _states.TryGetValue($"{item.Version}:{item.FileName}", out var state)
            return state.Status ?? ServerStatus.Downloading;

        var key = $"{item.Version}:{item.FileName}";
        _inFlight.Add(key);
        _states[key] = new DownloadState { Status = ServerStatus.Downloading, Item = item };

        try
        {
            var destDir = EnsurePatchDir();
            var filePath = Path.Combine(destDir, item.FileName);
            var existingSize = File.Exists(filePath) ? new FileInfo(filePath).LengthLong : 0L;

            if (existingSize > 0 && !await CheckIntegrityNeeded(item, filePath))
            {
                _states[key].Status = ServerStatus.Skipped;
                Console.WriteLine($"[Skip] {item.FileName} já válido no disco ({formatBytes(existingSize)})");
                return ServerStatus.Skipped;
            }

            // Reconcilia: se já existe mas hash não bate, apaga e baixa de novo
            if (existingSize > 0 && await CheckIntegrityRequired(item, filePath))
            {
                Console.WriteLine($"[Rewind] Hash inválido em {item.FileName}, removendo arquivo existente");
                File.Delete(filePath);
                existingSize = 0;
            }

            var chunkSize = 1_048_576; // 1 MB chunks
            var lastWritten = existingSize; // ponto de retomada
            var sentBytes = 0L;

            using var client = new HttpClient { BaseAddress = new Uri(_baseUrl) };
            var progress = new Progress<long>(v => sentBytes += v);

            for (var offset = 0; ; )
            {
                if (ct.IsCancellationRequested)
                {
                    Console.WriteLine($"[Abort] Cancelado em {item.FileName}");
                    _states[key].Status = ServerStatus.Resuming; // sinaliza retry
                    break;
                }

                // Range header opcional para HTTP/1.1 suportar resume via Content-Range
                var end = offset + chunkSize - 1;
                var range = $"bytes={offset}-{end}/*";

                using var request = new HttpRequestMessage(Method.Get, $"{_baseUrl}/{item.FileName}?version={item.Version}");
                request.Headers.Range = new RangeHeaderValue(offset, end);
                request.ResponseHeaders.EnableTrimming = false;

                var response = await client.SendAsync(request, ct);
                if (!response.IsSuccessStatusCode)
                {
                    Console.WriteLine($"[Err] HTTP {response.StatusCode} em {item.FileName} offset {offset}");
                    _states[key].Status = ServerStatus.ErrorUnavailable;
                    break;
                }

                using var stream = response.Content.ReadAsStream();
                if (stream is null) break;

                using var fs = new FileStream(filePath, FileMode.Create, FileAccess.Write, FileOptions.WriteThrough);
                var buffer = new byte[chunkSize];
                int read;
                while ((read = await stream.ReadAsync(buffer, 0, buffer.Length, ct)) > 0)
                {
                    fs.Write(buffer, 0, read);
                    lastWritten += read;
                    progress.Report(read);
                }

                // Verifica se o arquivo está completo após cada chunk (se soubermos o tamanho)
                if (item.ExpectedSizeBytes > 0 && lastWritten >= item.ExpectedSizeBytes)
                {
                    await VerifyAndFinishAsync(item, filePath, lastWritten);
                    _inFlight.Remove(key);
                    _states.Remove(key);
                    return ServerStatus.Completed;
                }

                offset += chunkSize;
                await Task.Delay(TimeSpan.FromMilliseconds(50), ct); // evita sobrecarga
            }

            // Finalizou sem completar (interrupção) → mantém arquivo parcial
            _states[key].Status = ServerStatus.Resuming;
        }
        catch (OperationCanceledException)
        {
            // Intencional - ignorado acima
        }
        catch (Exception ex)
        {
            Console.WriteLine($"[Exceção] {ex.Message}");
            _states[key].Status = ServerStatus.ErrorUnavailable;
        }
        finally
        {
            _inFlight.Remove(key);
        }

        return ServerStatus.Resuming; // sinaliza que vai precisar retry
    }

    private async Task<bool> CheckIntegrityNeeded(DownloadItem item, string filePath)
    {
        if (!File.Exists(filePath)) return true;
        try
        {
            var hash = await ComputeHashAsync(filePath, "sha256");
            // Compara com o hash esperado do servidor (se disponível)
            // Se o servidor retornar o hash esperado no status, faça a comparação aqui
            return false; // por enquanto assume que precisa baixar sempre que existir
        }
        catch
        {
            return true; // falha na verificação → força rebaixamento
        }
    }

    private async Task<bool> CheckIntegrityRequired(DownloadItem item, string filePath)
    {
        // Retorna true se o arquivo atual NÃO atende (precisa rebaixar)
        if (!File.Exists(filePath)) return true;
        try
        {
            var currentHash = await ComputeHashAsync(filePath, "sha256");
            // Se o servidor fornecer o hash esperado (ex: campo integrity no status), compare
            // Aqui usamos o valor fornecido no modelo do update
            // Se item.IntegrityHash != currentHash → precisa rebaixar
            return item.IntegrityHash != currentHash;
        }
        catch
        {
            return true;
        }
    }

    private async Task<string> ComputeHashAsync(string path, string algorithm)
    {
        using var fs = new FileStream(path, FileMode.Open, FileAccess.Read);
        var hash = new SHA256HashAlgorithm();
        var data = new byte[4096];
        int len;
        while ((len = await fs.ReadAsync(data, 0, data.Length)) > 0)
            hash.Update(data, 0, len);
        return Convert.ToHexString(hash.Compute(hash.HashSize));
    }

    private async Task VerifyAndFinishAsync(DownloadItem item, string filePath, long finalBytes)
    {
        if (!File.Exists(filePath))
        {
            Console.WriteLine($"[Falha] Arquivo incompleto: {item.FileName}");
            throw new InvalidOperationException("Arquivo incompleto.");
        }

        var actual = new FileInfo(filePath).LengthLong;
        if (item.ExpectedSizeBytes > 0 && actual != item.ExpectedSizeBytes)
        {
            Console.WriteLine($"[Tamanho divergente] esperado {formatBytes(item.ExpectedSizeBytes)} got {formatBytes(actual)}");
            // Decide: apagar e refazer ou manter? Recomendado apagar e refazer
            File.Delete(filePath);
            actual = 0;
        }

        var hashOk = await ComputeHashAsync(filePath, "sha256") == item.IntegrityHash.Trim();
        if (!hashOk)
        {
            Console.WriteLine($"[Hash inválido] {item.FileName}");
            File.Delete(filePath);
            throw new InvalidOperationException("Hash não confere.");
        }

        var dest = Path.Combine(_patchDir, $"{item.Version}_{item.FileName}_ok");
        File.Move(filePath, dest); // renomeia para evitar sobrescrever outro
        _states["${key}"].Status = ServerStatus.Completed;
    }

    /// <summary>
    /// Reinicia o download dos itens que estavam em progresso (Resuming).
    /// Chama-se automaticamente quando o processo detecta interrupção.
    /// </summary>
    public async Task<ServerStatus> RetryAsync(IEnumerable<DownloadItem> items, CancellationToken ct = default)
    {
        foreach (var item in items)
        {
            var key = $"{item.Version}:{item.FileName}";
            if (_states.TryGetValue(key, out var state) && state.Status == ServerStatus.Resuming)
            {
                Console.WriteLine($"[Retry] Reiniciando download de {item.FileName}...");
                _ = Task.Run(() => DownloadAsync(item, ct));
            }
        }
        return ServerStatus.Resuming;
    }

    // ---------- Utility ----------

    private static string formatBytes(long bytes)
    {
        if (bytes < 1024) return $"{bytes} B";
        if (bytes < 1024 * 1024) return $"{bytes / 1024} KB";
        if (bytes < 1024 * 1024 * 1024) return $"{bytes / (1024 * 1024)} MB";
        return $"{bytes / (1024 * 1024 * 1024)} GB";
    }
}

internal class DownloadState
{
    public ServerStatus Status { get; set; }
    public DownloadItem Item { get; set; }
}
